const PYKARA_COORDS=[11.4633,76.6067],HEIGHT_COMPARISONS=[{name:"Pykara Falls (lower)",heightMeters:61,note:"The taller of the two main cascades, ~61m (200 ft)"},{name:"Pykara Falls (upper)",heightMeters:55,note:"The upper cascade, ~55m (180 ft)"},{name:"Qutub Minar (Delhi)",heightMeters:73,note:"Tallest brick minaret in the world, for comparison"},{name:"Jog Falls (Karnataka)",heightMeters:253,note:"India's highest un-tiered waterfall"}],STRUCTURE_STAGES=[{stage:"1",title:"Mukurthi Source",img:"https://images.unsplash.com/photo-1587582423116-ec07293f0395?auto=format&fit=crop&q=80&w=800",alt:"Misty highland grassland and shola forest at a Nilgiri mountain peak",text:"The Pykara river rises at Mukurthi Peak inside Mukurthi National Park, fed by the shola-grassland ecosystem typical of the upper Nilgiris, then flows north before turning west toward the plateau edge."},{stage:"2",title:"Pykara Dam & Lake",img:"https://images.unsplash.com/photo-1470770903676-69b98201ea1c?auto=format&fit=crop&q=80&w=800",alt:"A calm reservoir lake surrounded by pine trees in a misty hill landscape",text:"Downstream, the river is dammed to form Pykara Lake, part of a major hydroelectric project (including the Pykara Ultimate Stage Hydro Electric Plant). The reservoir is also a popular boating spot before the river continues toward the falls."},{stage:"3",title:"Upper Falls (~55m)",img:"https://images.unsplash.com/photo-1508739773434-c26b3d09e071?auto=format&fit=crop&q=80&w=800",alt:"A waterfall cascading over a rocky cliff edge into a forested valley",text:"As the river reaches the edge of the Nilgiri plateau, it drops through a series of cascades; the first of the two named falls plunges about 55 metres over the escarpment."},{stage:"4",title:"Lower Falls (~61m)",img:"https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&q=80&w=800",alt:"A tall waterfall dropping through dense forest, the tallest of a series of cascades",text:"The second and taller drop, at roughly 61 metres, follows shortly after — together the two falls are what visitors know as Pykara Falls, framed by dense forest on the valley walls."}],SEASONAL_DATA=[{season:"Monsoon to Winter (Aug–Jan)",badgeClass:"badge-monsoon",img:"https://images.unsplash.com/photo-1622401467213-a2fecad55b93?auto=format&fit=crop&q=80&w=600",alt:"A waterfall in strong, full flow surrounded by lush green forest",title:"Full & Lush",text:"The falls run at their fullest and the surrounding forest is at its greenest — widely considered the best window to visit, with pleasant hill-station weather."},{season:"Summer (Feb–May)",badgeClass:"badge-winter",img:"https://images.unsplash.com/photo-1601582589907-f92af5ed9db8?auto=format&fit=crop&q=80&w=600",alt:"A reduced, gentler waterfall flow over rocks in drier conditions",title:"Reduced & Gentle",text:"Flow eases considerably in the drier months, exposing more rock along the cascades. Still scenic, but a noticeably quieter version of the falls."}],GALLERY_IMAGES=[{url:"https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&q=80&w=800",caption:"Pykara Falls' lower, taller cascade dropping through the forest",category:"Hero Waterfall"},{url:"https://images.unsplash.com/photo-1470770903676-69b98201ea1c?auto=format&fit=crop&q=80&w=800",caption:"Pykara Lake and reservoir, formed by the dam upstream of the falls",category:"River Landscape"},{url:"https://images.unsplash.com/photo-1587582423116-ec07293f0395?auto=format&fit=crop&q=80&w=800",caption:"Rolling grassy downs and shola forest typical of the Nilgiri plateau",category:"Nilgiri Landscape"},{url:"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&q=80&w=800",caption:"The falls viewpoint framed by pine and eucalyptus forest",category:"Viewpoint"}],NEARBY_ATTRACTIONS=[{name:"Pykara Lake & Boat House",distance:"~2 km",lat:11.452,lng:76.621,description:"A reservoir on the Pykara river with boating facilities, ringed by pine forest."},{name:"Mukurthi National Park",distance:"~15 km",lat:11.3667,lng:76.5333,description:"Protected shola-grassland habitat at the Pykara river's source, home to the Nilgiri tahr."},{name:"Doddabetta Peak",distance:"~25 km",lat:11.4064,lng:76.7378,description:"The highest peak in the Nilgiris, with a telescope house and panoramic views over Ooty."},{name:"Shooting Point",distance:"~5 km",lat:11.42,lng:76.68,description:"A scenic overlook popular for the many Indian films shot in the surrounding Wenlock Downs."}],REFERENCES=[{text:"Wikipedia — Pykara, Nilgiris district, Tamil Nadu.",link:"https://en.wikipedia.org/wiki/Pykara"},{text:"Tamil Nadu Tourism — Pykara, Ooty.",link:"https://www.tamilnadutourism.tn.gov.in/destinations/pykara-ooty"},{text:"The Nilgiris District Administration — Pykara, Ooty.",link:"https://nilgiris.nic.in/tourist-place/pykara-ooty/"},{text:"Images: Unsplash contributors (used under the Unsplash License for demonstration purposes).",link:"https://unsplash.com/license"}];"undefined"!=typeof module&&module.exports&&(module.exports={PYKARA_COORDS:PYKARA_COORDS,HEIGHT_COMPARISONS:HEIGHT_COMPARISONS,STRUCTURE_STAGES:STRUCTURE_STAGES,SEASONAL_DATA:SEASONAL_DATA,GALLERY_IMAGES:GALLERY_IMAGES,NEARBY_ATTRACTIONS:NEARBY_ATTRACTIONS,REFERENCES:REFERENCES});